report=json.loads((R/'integration-draft.json').read_text());cases={c['commit'][:8]:c for c in report['cases']};manifest=json.loads((R/'manifest-draft.json').read_text());cs={c['commit'][:8]:c for c in manifest['candidates']};records=[]
